/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_COMMON_ADMIN_GEOGRAPHY
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_LOCATION   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_LOCATION_HK
   hashdiff    : SAT_COMMON_ADMIN_GEOGRAPHY_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__ADD_LINE1_ADD_LINE2_ADD_LINE3_ADD_LINE4_CITY_STATE_STATE_CODE_PINCODE))) as HUB_LOCATION_HK
        , UT_FLAG as UNION_TERRITORY_INDICATOR
        , 'BJAZ_BRANCH_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_branch_master') }}
    where (md5(normalise(upper(nullif(trim( coalesce(ADD_LINE1,'') || '|' || coalesce(ADD_LINE2,'') || '|' || coalesce(ADD_LINE3,'') || '|' || coalesce(ADD_LINE4,'') || '|' || coalesce(CITY,'') || '|' || coalesce(STATE,'') || '|' || coalesce(STATE_CODE,'') || '|' || coalesce(PINCODE,'') ), '|||||||'))))) is not null
),

resolved as (
    select
        HUB_LOCATION_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then UNION_TERRITORY_INDICATOR end) as UNION_TERRITORY_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_LOCATION_HK
),

hashed as (
    select
        *,
        case when UNION_TERRITORY_INDICATOR is not null
                     then md5(upper(coalesce(cast(UNION_TERRITORY_INDICATOR as varchar), '')))
                end as SAT_COMMON_ADMIN_GEOGRAPHY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_LOCATION_HK is not null
  and SAT_COMMON_ADMIN_GEOGRAPHY_HASHDIFF is not null
